<script setup lang="ts">
import {ref,shallowRef} from 'vue'
import type {NativeClient} from '../services/native-client'
import type {ActivityEvent} from '../../../server/activity/records'
import Icon from './Icon.vue'
const props=defineProps<{client:NativeClient;diagrams:Array<{id:string;title:string}>}>()
const visible=ref(false),working=ref(false),diagramId=ref(''),channel=ref(''),actor=ref(''),events=shallowRef<ActivityEvent[]>([]),cursor=ref<string>(),error=ref('')
let generation=0
const actions:Record<string,string>={create:'创建图形','editor-save':'编辑画布','collaborative-editor-save':'编辑画布','content-patch':'修改内容','ai-content-patch':'AI 修改内容','ai-content-update':'AI 更新内容','import-content':'导入图形','import-project':'导入工作区文件','import-drawio':'导入原生图形',move:'移动分组',delete:'移入回收站',restore:'恢复图形',purge:'永久删除','create-group':'创建分组','rename-group':'重命名分组','delete-group':'删除分组','configure-rendering':'调整排版','business-mapping':'映射业务属性'}
function title(event:ActivityEvent){return props.diagrams.find(d=>d.id===event.diagramId)?.title??event.diagramId??'文件夹'}
function summary(event:ActivityEvent){const result:string[]=[];for(const [key,label] of [['nodes','节点'],['edges','连线'],['lanes','泳道'],['phases','阶段'],['groups','分层']] as const){const value=event.summary[key];if(value?.added)result.push('新增'+value.added+label);if(value?.updated)result.push('修改'+value.updated+label);if(value?.removed)result.push('删除'+value.removed+label)}if(event.summary.contentFields?.length)result.push('修改'+event.summary.contentFields.join('、'));if(event.summary.renderingChanged)result.push('调整图形样式或位置');return result.join('；')}
async function load(more=false){const token=++generation;working.value=true;error.value='';try{const page=await props.client.activity({...(diagramId.value?{diagramId:diagramId.value}:{}),...(channel.value?{channel:channel.value as 'web'|'mcp'|'system'}:{}),...(actor.value.trim()?{actorUserId:actor.value.trim()}:{}),...(more&&cursor.value?{cursor:cursor.value}:{}),limit:50});if(token!==generation)return;events.value=more?[...events.value,...page.items]:page.items;cursor.value=page.nextCursor}catch(e){if(token===generation)error.value=e instanceof Error?e.message:String(e)}finally{if(token===generation)working.value=false}}
function show(id?:string){diagramId.value=id??'';visible.value=true;void load()}
defineExpose({show})
</script>
<template><div v-if="visible" class="studio-overlay" @click.self="visible=false"><section class="studio-dialog activity-dialog" role="dialog" aria-modal="true" aria-label="操作记录"><header class="studio-dialog-heading"><h2>操作记录</h2><button class="studio-icon" aria-label="关闭操作记录" @click="visible=false"><Icon name="close" :size="16"/></button></header><div class="activity-filters"><select v-model="diagramId" aria-label="记录图形" :disabled="working" @change="load()"><option value="">工作区全部图形</option><option v-for="diagram in diagrams" :key="diagram.id" :value="diagram.id">{{diagram.title}}</option></select><select v-model="channel" aria-label="记录来源" :disabled="working" @change="load()"><option value="">全部来源</option><option value="web">人工编辑</option><option value="mcp">MCP</option><option value="system">系统</option></select><button class="studio-text-btn" :disabled="working" @click="load()">刷新</button></div><div class="activity-list"><article v-for="event in events" :key="event.eventId"><div><strong>{{event.actor.userDisplayName||event.actor.userId||'系统'}}</strong><span>{{actions[event.action]||event.action}}</span><time>{{new Date(event.occurredAt).toLocaleString('zh-CN',{hour12:false})}}</time></div><p>{{title(event)}}<span v-if="event.toRevision"> · r{{event.toRevision}}</span></p><small v-if="summary(event)">{{summary(event)}}</small><details v-if="event.summary.nodes?.changed?.length||event.summary.edges?.changed?.length"><summary>变更字段</summary><p v-for="change in [...(event.summary.nodes?.changed??[]),...(event.summary.edges?.changed??[])]" :key="change.id">{{change.id}}{{change.fields.length?' · '+change.fields.join('、'):''}}</p></details></article><p v-if="!events.length&&!working" class="workspace-empty">暂无记录</p><p v-if="working" role="status">读取中…</p><p v-if="error" role="alert">{{error}}</p></div><button v-if="cursor" class="studio-text-btn" :disabled="working" @click="load(true)">更早记录</button></section></div></template>
<style scoped>
.activity-dialog{width:700px;max-width:92vw}.activity-filters{display:flex;gap:10px;margin:14px 0}.activity-filters select{min-width:0;max-width:340px;padding:6px;border:1px solid var(--fm-border,#dde1eb);border-radius:7px;background:var(--fm-surface,#fff);color:inherit}.activity-list{max-height:60vh;overflow:auto}.activity-list article{padding:13px 0;border-bottom:1px solid var(--fm-border,#e5e7ef)}.activity-list article>div{display:flex;align-items:center;gap:9px;font-size:13px}.activity-list time{margin-left:auto;font-size:11px;color:var(--fm-muted,#7e8696)}.activity-list p{margin:6px 0;font-size:12px;overflow-wrap:anywhere}.activity-list small,.activity-list summary{font-size:12px;color:var(--fm-muted,#7e8696)}.activity-list details{margin-top:7px}
</style>
